#!/usr/bin/env bash
# Deploys Prometheus, Alertmanager and Grafana into k3s (cluster admin). Grafana's admin password
# comes from ~/lab-secrets (generated by k8s/bootstrap/create-secrets.sh) and is stored as a Secret.
set -euo pipefail
cd "$(dirname "$0")"
kubectl apply -f prometheus.yaml
kubectl -n monitoring create secret generic grafana-admin \
  --from-file=admin-password="$HOME/lab-secrets/grafana-admin-password" --dry-run=client -o yaml | kubectl apply -f -
kubectl apply -f alertmanager.yaml -f grafana.yaml
kubectl -n monitoring rollout status deploy/prometheus deploy/alertmanager deploy/grafana --timeout=300s
